CREATE OR REPLACE FUNCTION private.org_role_impact(b jsonb,a jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE u record;x jsonb;y jsonb;diff jsonb;result jsonb:='[]';BEGIN FOR u IN SELECT id,full_name FROM profiles LOOP IF private.org_role_rules(u.id,b) IS NOT DISTINCT FROM private.org_role_rules(u.id,a) THEN CONTINUE;END IF;x:=private.base_effective(u.id,b);y:=private.base_effective(u.id,a);SELECT coalesce(jsonb_agg(jsonb_build_object('key',n->>'key','label',n->>'label','before',o,'after',n)),'[]') INTO diff FROM jsonb_array_elements(y)n JOIN jsonb_array_elements(x)o ON n->>'key'=o->>'key' WHERE n IS DISTINCT FROM o;IF jsonb_array_length(diff)>0 THEN result:=result||jsonb_build_array(jsonb_build_object('user_id',u.id,'name',u.full_name,'changes',diff));END IF;END LOOP;RETURN result;END $$;